WITH base AS (SELECT * FROM employees WHERE manager_id IN (22, 26, 40) AND full_name LIKE '%Wong%'), hire_cohort_summary AS (SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END hire_cohort, SORT_ARRAY(COLLECT_SET(job_title)) job_title_list, ROUND(AVG(salary), 2) avg_salary FROM base GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT hire_cohort, job_title_list, avg_salary FROM hire_cohort_summary ORDER BY hire_cohort
